             F (Z_to_bv 64 0x074598) fc None m' (seg_rom asegs)
    /\ munch W m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells asegs m' (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 ra]
    /\ rw_cells asegs m' 1203800 [C8 (wz 4096); C8 (wz pa); C8 (wz pa)]
    /\ rw_cells asegs m' 1203848 [C8 (wz nres); C8 (wz (nch - 1)); C8 (wz 0)]
